import sys

def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def fib(k):
        if k <= 0:
            return 0
        if k == 1:
            return 1
        return fib(k-1) + fib(k-2)
    print(fib(n))

if __name__ == "__main__":
    solve()
